  { id: "std-104", admissionNo: "ADM-2026-004", name: "Isha Mehra", grade: "KG - Sunflower", parentName: "Deepak Mehra", phone: "+91 99887 66554", feeStatus: "paid", attendancePct: 100, performanceGrade: "O" }
