// Helper: Resolve or create book in memory and public.library_books table
async function resolveOrCreateLibraryBook(orgId, bookData) {
  if (!bookData || !bookData.title) return { book: null, db_id: null };

  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const targetId = bookData.id || bookData.bookId;

  let memoryBook = ERP_LIBRARY_BOOKS.find(b => 
    (!b.organization_id || b.organization_id === orgId) && 
    (b.id === targetId || b.db_id === targetId || (b.isbn && bookData.isbn && b.isbn === bookData.isbn) || (b.title && b.title.toLowerCase() === bookData.title.toLowerCase()))
  );

  let dbBookId = memoryBook?.db_id || (isUuid.test(targetId) ? targetId : null);

  if (supabase) {
    try {
      if (!dbBookId) {
        let q = supabase.from("library_books").select("*").eq("organization_id", orgId);
        if (isUuid.test(targetId)) {
          q = q.eq("id", targetId);
        } else if (bookData.isbn && bookData.isbn.trim()) {
          q = q.eq("isbn", bookData.isbn.trim());
        } else {
          q = q.eq("title", bookData.title.trim());
        }
        const { data: dbExisting } = await q.maybeSingle();
        if (dbExisting) {
          dbBookId = dbExisting.id;
          if (memoryBook) memoryBook.db_id = dbExisting.id;
          return { book: memoryBook || dbExisting, db_id: dbBookId, dbBook: dbExisting };
        }
      }

      if (!dbBookId) {
        const count = Math.max(1, parseInt(bookData.totalCopies || bookData.copiesCount, 10) || 1);
        const { data: newDbBook, error: insErr } = await supabase
          .from("library_books")
          .insert([{
            organization_id: orgId,
            isbn: bookData.isbn ? bookData.isbn.trim() : null,
            title: bookData.title.trim(),
            author: bookData.author || bookData.authorName || null,
            category: bookData.category || bookData.categoryName || "General",
            publisher: bookData.publisher || bookData.publisherName || null,
            total_copies: count,
            available_copies: count
          }])
          .select()
          .maybeSingle();

        if (newDbBook) {
          dbBookId = newDbBook.id;
          if (memoryBook) memoryBook.db_id = newDbBook.id;
          return { book: memoryBook || newDbBook, db_id: dbBookId, dbBook: newDbBook };
        }
      }
    } catch (e) {
      console.warn("[DB] resolveOrCreateLibraryBook exception:", e.message);
    }
  }

  return { book: memoryBook, db_id: dbBookId || memoryBook?.id };
}

// Helper: Resolve library member asynchronously (checking in-memory and Supabase DB)
async function resolveLibraryMemberAsync(orgId, memberType, memberId) {
  let mem = resolveLibraryMember(memberType, memberId);
  if (mem) return mem;

  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (!supabase) return null;

  try {
    if (memberType === 'student') {
      let q = supabase.from("students").select("*");
      if (orgId) q = q.eq("organization_id", orgId);
      if (isUuid.test(memberId)) {
        q = q.eq("id", memberId);
      } else {
        q = q.eq("admission_no", memberId);
      }
      const { data: dbStd } = await q.maybeSingle();
      if (dbStd) {
        let memObj = ERP_STUDENTS.find(s => s.id === dbStd.id || s.db_id === dbStd.id);
        if (!memObj) {
          memObj = {
            id: dbStd.id,
            db_id: dbStd.id,
            organization_id: dbStd.organization_id || orgId,
            name: `${dbStd.first_name || ''} ${dbStd.last_name || ''}`.trim() || "Student",
            admissionNo: dbStd.admission_no,
            grade: dbStd.grade || "Class 10",
            section: dbStd.section || "A",
            email: dbStd.email || "",
            phone: dbStd.phone || ""
          };
          ERP_STUDENTS.push(memObj);
        }
        return resolveLibraryMember('student', dbStd.id);
      }
    } else {
      let q = supabase.from("staff").select("*");
      if (orgId) q = q.eq("organization_id", orgId);
      if (isUuid.test(memberId)) {
        q = q.eq("id", memberId);
      } else {
        q = q.eq("employee_code", memberId);
      }
      const { data: dbStf } = await q.maybeSingle();
      if (dbStf) {
        let memObj = ERP_STAFF.find(s => s.id === dbStf.id || s.db_id === dbStf.id);
        if (!memObj) {
          memObj = {
            id: dbStf.id,
            db_id: dbStf.id,
            organization_id: dbStf.organization_id || orgId,
            name: `${dbStf.first_name || ''} ${dbStf.last_name || ''}`.trim() || "Staff Member",
            empId: dbStf.employee_code,
            role: dbStf.designation?.toLowerCase().includes("teacher") || dbStf.designation?.toLowerCase().includes("professor") ? "teacher" : "staff",
            department: dbStf.department || "Academics",
            designation: dbStf.designation || "Faculty",
            email: dbStf.email || "",
            phone: dbStf.phone || ""
          };
          ERP_STAFF.push(memObj);
        }
        return resolveLibraryMember(memObj.role === 'teacher' ? 'teacher' : 'staff', dbStf.id);
      }
    }
  } catch (e) {
    console.warn("[DB] resolveLibraryMemberAsync exception:", e.message);
  }

  return null;
}

// Helper: Resolve borrower (student or staff) DB UUID for library transaction
async function resolveLibraryBorrowerDbId(orgId, memberType, memberId) {
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  let studentDbId = null;
  let staffDbId = null;

  if (memberType === "student") {
    const st = ERP_STUDENTS.find(s => 
      (!s.organization_id || s.organization_id === orgId) && 
      (s.id === memberId || s.admissionNo === memberId || s.db_id === memberId)
    );
    if (st && st.db_id) {
      studentDbId = st.db_id;
    } else if (isUuid.test(memberId)) {
      studentDbId = memberId;
    } else if (supabase) {
      const { data: dbStd } = await supabase
        .from("students")
        .select("id")
        .eq("organization_id", orgId)
        .or(`admission_no.eq.${memberId},id.eq.${isUuid.test(memberId) ? memberId : '00000000-0000-0000-0000-000000000000'}`)
        .maybeSingle();
      if (dbStd) studentDbId = dbStd.id;
    }
  } else {
    const sf = ERP_STAFF.find(s => 
      (!s.organization_id || s.organization_id === orgId) && 
      (s.id === memberId || s.empId === memberId || s.db_id === memberId)
    );
    if (sf && sf.db_id) {
      staffDbId = sf.db_id;
    } else if (isUuid.test(memberId)) {
      staffDbId = memberId;
    } else if (supabase) {
      const { data: dbStf } = await supabase
        .from("staff")
        .select("id")
        .eq("organization_id", orgId)
        .or(`employee_code.eq.${memberId},id.eq.${isUuid.test(memberId) ? memberId : '00000000-0000-0000-0000-000000000000'}`)
        .maybeSingle();
      if (dbStf) staffDbId = dbStf.id;
    }
  }

  return { studentDbId, staffDbId };
}

// Helper: Persist circulation transaction into public.library_transactions
async function recordLibraryTransactionDb(orgId, txData) {
  if (!txData) return null;

  const bookRes = await resolveOrCreateLibraryBook(orgId, { 
    id: txData.bookId, 
    title: txData.bookTitle || "Library Book" 
  });
  const dbBookId = bookRes.db_id;
  const borrower = await resolveLibraryBorrowerDbId(orgId, txData.memberType || "student", txData.memberId);

  if (supabase && dbBookId && (borrower.studentDbId || borrower.staffDbId)) {
    try {
      const { data: dbTx, error: insErr } = await supabase
        .from("library_transactions")
        .insert([{
          organization_id: orgId,
          book_id: dbBookId,
          student_id: borrower.studentDbId || null,
          staff_id: borrower.staffDbId || null,
          issued_at: txData.issuedAt || new Date().toISOString(),
          due_at: txData.dueAt || null,
          fine: Number(txData.fine || 0)
        }])
        .select()
        .maybeSingle();

      if (insErr) {
        console.warn("[DB] Library transaction insert warning:", insErr.message);
      } else if (dbTx) {
        return dbTx;
      }
    } catch (e) {
      console.warn("[DB] recordLibraryTransactionDb exception:", e.message);
    }
  }
  return null;
}

// Helper: Update circulation transaction on return in public.library_transactions
async function updateLibraryTransactionReturnDb(orgId, txId, returnedAt, fine = 0) {
  if (!txId) return null;

  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  let memoryTx = ERP_LIBRARY_TRANSACTIONS.find(t => 
    (!t.organization_id || t.organization_id === orgId) && 
    (t.id === txId || t.db_id === txId)
  );

  let targetDbId = memoryTx?.db_id || (isUuid.test(txId) ? txId : null);

  if (supabase && targetDbId) {
    try {
      const { data, error } = await supabase
        .from("library_transactions")
        .update({
          returned_at: returnedAt || new Date().toISOString(),
          fine: Number(fine || 0)
        })
        .eq("id", targetDbId)
        .select();

      if (error) {
        console.warn("[DB] Library transaction return update warning:", error.message);
      } else {
        return data;
      }
    } catch (e) {
      console.warn("[DB] updateLibraryTransactionReturnDb exception:", e.message);
    }
  }
  return null;
}

// 10a. GET /api/erp/library/overview - Real aggregated dashboard KPIs & widgets
app.get("/api/erp/library/overview", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const now = new Date();

  // Books metrics
  const activeBooks = ERP_LIBRARY_BOOKS.filter(b => b.organization_id === orgId && b.status !== "archived");
  const totalBooks = activeBooks.length;
  const copies = ERP_LIBRARY_COPIES.filter(c => c.organization_id === orgId && c.status !== "retired");
  const totalCopies = copies.length;
  const availableCopies = copies.filter(c => c.status === "available").length;

  // Transactions metrics
  const activeTransactions = ERP_LIBRARY_TRANSACTIONS.filter(t => t.organization_id === orgId && (t.status === "issued" || t.status === "overdue"));
  const issuedBooks = activeTransactions.length;
  const overdueTransactions = activeTransactions.filter(t => t.status === "overdue" || (t.dueAt && new Date(t.dueAt) < now));
  const overdueBooks = overdueTransactions.length;

  // Reservations & Fines
  const activeReservations = ERP_LIBRARY_RESERVATIONS.filter(r => r.organization_id === orgId && (r.status === "pending" || r.status === "ready"));
  const reservedBooks = activeReservations.length;
  const orgFines = ERP_LIBRARY_FINES.filter(f => f.organization_id === orgId);
  const outstandingFines = orgFines.filter(f => f.status === "outstanding").reduce((sum, f) => sum + (Number(f.amount) || 0), 0);
  const collectedFines = orgFines.filter(f => f.status === "paid").reduce((sum, f) => sum + (Number(f.amount) || 0), 0);
  const waivedFines = orgFines.filter(f => f.status === "waived").reduce((sum, f) => sum + (Number(f.amount) || 0), 0);

  // Active library members (unique borrowers)
  const uniqueMemberIds = new Set(activeTransactions.map(t => t.memberId));
  const activeMembers = uniqueMemberIds.size;

  // Recent activity
  const recentIssues = ERP_LIBRARY_TRANSACTIONS
    .filter(t => t.organization_id === orgId)
    .sort((a, b) => new Date(b.issuedAt) - new Date(a.issuedAt))
    .slice(0, 5);

  const recentReturns = ERP_LIBRARY_TRANSACTIONS
    .filter(t => t.organization_id === orgId && t.returnedAt)
    .sort((a, b) => new Date(b.returnedAt) - new Date(a.returnedAt))
    .slice(0, 5);

  // Books due today or within 24h
  const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const endOfDay = startOfDay + 86400000;
  const booksDueToday = activeTransactions.filter(t => {
    const dueTime = new Date(t.dueAt).getTime();
    return dueTime >= startOfDay && dueTime <= endOfDay;
  });

  // Low stock / no available copy
  const lowStockBooks = activeBooks.filter(b => b.availableCopies <= 1);

  // Popular books based on transaction history
  const issueCounts = {};
  ERP_LIBRARY_TRANSACTIONS.filter(t => t.organization_id === orgId).forEach(t => {
    issueCounts[t.bookId] = (issueCounts[t.bookId] || 0) + 1;
  });
  const popularBooks = activeBooks
    .map(b => ({ ...b, circulationCount: issueCounts[b.id] || 0 }))
    .sort((a, b) => b.circulationCount - a.circulationCount)
    .slice(0, 5);

  // Category breakdown
  const categorySummary = ERP_LIBRARY_CATEGORIES.filter(c => c.organization_id === orgId).map(cat => {
    const catBooks = activeBooks.filter(b => b.categoryId === cat.id || b.category === cat.name);
    const catCopies = catBooks.reduce((s, b) => s + b.totalCopies, 0);
    return {
      categoryId: cat.id,
      categoryName: cat.name,
      bookCount: catBooks.length,
      copyCount: catCopies
    };
  });

  res.json({
    success: true,
    totalBooks,
    totalCopies,
    availableCopies,
    issuedBooks,
    overdueBooks,
    reservedBooks,
    outstandingFines,
    activeMembers,
    circulationRatePercent: totalCopies > 0 ? Math.round((issuedBooks / totalCopies) * 100) : 0,
    metrics: {
      totalBooks,
      totalCopies,
      availableCopies,
      issuedBooks,
      overdueBooks,
      reservedBooks,
      outstandingFines,
      activeMembers,
      circulationRatePercent: totalCopies > 0 ? Math.round((issuedBooks / totalCopies) * 100) : 0
    },
    recentIssues,
    recentReturns,
    overdueList: overdueTransactions,
    popularBooks,
    booksDueToday,
    lowStockBooks,
    fineSummary: {
      totalFinesCollected: collectedFines,
      totalOutstanding: outstandingFines,
      totalWaived: waivedFines,
      totalRecords: orgFines.length
    },
    categorySummary
  });
});

// 10b. Books CRUD Endpoints
app.get("/api/erp/library/books", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { search, category, status, availability, page = 1, limit = 20 } = req.query;

  let list = ERP_LIBRARY_BOOKS.filter(b => b.organization_id === orgId);

  if (search) {
    const q = search.toLowerCase();
    list = list.filter(b =>
      b.title.toLowerCase().includes(q) ||
      (b.isbn && b.isbn.toLowerCase().includes(q)) ||
      (b.author && b.author.toLowerCase().includes(q)) ||
      (b.shelfLocation && b.shelfLocation.toLowerCase().includes(q))
    );
  }

  if (category && category !== "all") {
    list = list.filter(b => b.category === category || b.categoryId === category || b.categoryName === category);
  }

  if (status && status !== "all") {
    list = list.filter(b => b.status === status);
  } else {
    list = list.filter(b => b.status !== "archived");
  }

  if (availability === "available") {
    list = list.filter(b => b.availableCopies > 0);
  } else if (availability === "unavailable") {
    list = list.filter(b => b.availableCopies === 0);
  }

  const total = list.length;
  const p = Math.max(1, parseInt(page, 10));
  const l = Math.max(1, parseInt(limit, 10));
  const paginated = list.slice((p - 1) * l, p * l);

  res.json({
    success: true,
    books: paginated,
    pagination: {
      total,
      page: p,
      limit: l,
      totalPages: Math.ceil(total / l)
    }
  });
});

app.post("/api/erp/library/books", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const {
    title,
    subtitle = "",
    isbn = "",
    author = "Unknown Author",
    authorId = null,
    publisher = "",
    publisherId = null,
    category = "General",
    categoryId = null,
    edition = "1st Edition",
    publicationYear = new Date().getFullYear(),
    language = "English",
    subject = "",
    description = "",
    pages = 0,
    shelfLocation = "Rack Main",
    coverImageUrl = "",
    copiesCount = 1,
    acquisitionCost = 0
  } = req.body;

  if (!title || !title.trim()) {
    return res.status(400).json({ success: false, message: "Book title is required" });
  }

  const count = Math.max(1, parseInt(copiesCount, 10) || 1);
  const newBook = {
    id: `bk-${Date.now().toString().slice(-4)}`,
    organization_id: orgId,
    title: title.trim(),
    subtitle: subtitle.trim(),
    isbn: isbn.trim(),
    authorId,
    author: author.trim(),
    authorName: author.trim(),
    publisherId,
    publisherName: publisher.trim(),
    categoryId,
    category: category.trim(),
    categoryName: category.trim(),
    edition: edition.trim(),
    publicationYear: parseInt(publicationYear, 10) || new Date().getFullYear(),
    language,
    subject: subject.trim(),
    description: description.trim(),
    pages: parseInt(pages, 10) || 0,
    shelfLocation: shelfLocation.trim(),
    coverImageUrl: coverImageUrl.trim() || "https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=200&auto=format&fit=crop&q=80",
    totalCopies: count,
    availableCopies: count,
    status: "active",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  ERP_LIBRARY_BOOKS.unshift(newBook);

  // Persist to Supabase public.library_books table
  const dbBookRes = await resolveOrCreateLibraryBook(orgId, newBook);
  if (dbBookRes && dbBookRes.db_id) {
    newBook.db_id = dbBookRes.db_id;
  }

  // Auto-generate physical copies
  const addedCopies = [];
  for (let i = 1; i <= count; i++) {
    const accNum = `ACC-${1000 + ERP_LIBRARY_COPIES.length + 1}`;
    const newCopy = {
      id: `cpy-${Date.now().toString().slice(-4)}-${i}`,
      organization_id: orgId,
      bookId: newBook.id,
      accessionNumber: accNum,
      barcode: `BC-${accNum}`,
      copyNumber: i,
      condition: "new",
      acquisitionDate: new Date().toISOString().slice(0, 10),
      acquisitionCost: Number(acquisitionCost) || 0,
      shelfLocation: newBook.shelfLocation,
      status: "available",
      notes: "Newly acquired catalog copy",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    ERP_LIBRARY_COPIES.push(newCopy);
    addedCopies.push(newCopy);
  }

  // Update category bookCount
  const cat = ERP_LIBRARY_CATEGORIES.find(c => c.name === newBook.category || c.id === newBook.categoryId);
  if (cat) {
    cat.bookCount = (cat.bookCount || 0) + 1;
  }

  // Audit log
  ERP_AUDIT_LOGS.unshift({
    id: `aud-${Date.now()}`,
    action: "erp.library_book_created",
    user_email: req.user?.email || "librarian@dpsheritage.edu.in",
    target_type: "library_book",
    target_id: newBook.id,
    ip_address: req.ip || "127.0.0.1",
    timestamp: new Date().toISOString()
  });

  res.status(201).json({
    success: true,
    message: "Book added to catalogue with " + count + " physical copies",
    book: newBook,
    copies: addedCopies
  });
});

app.get("/api/erp/library/books/:id", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const book = ERP_LIBRARY_BOOKS.find(b => (b.id === req.params.id || b.db_id === req.params.id) && b.organization_id === orgId);
  if (!book) {
    return res.status(404).json({ success: false, message: "Book not found in catalogue" });
  }

  const copies = ERP_LIBRARY_COPIES.filter(c => (c.bookId === book.id || c.bookId === book.db_id) && c.organization_id === orgId);
  const activeLoans = ERP_LIBRARY_TRANSACTIONS.filter(t => (t.bookId === book.id || t.bookId === book.db_id) && (t.status === "issued" || t.status === "overdue"));
  const reservations = ERP_LIBRARY_RESERVATIONS.filter(r => (r.bookId === book.id || r.bookId === book.db_id) && (r.status === "pending" || r.status === "ready"));

  res.json({
    success: true,
    book: {
      ...book,
      copies,
      activeLoans,
      reservations
    }
  });
});

app.patch("/api/erp/library/books/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const book = ERP_LIBRARY_BOOKS.find(b => (b.id === req.params.id || b.db_id === req.params.id) && b.organization_id === orgId);
  if (!book) {
    return res.status(404).json({ success: false, message: "Book not found in catalogue" });
  }

  const allowedFields = [
    "title", "subtitle", "isbn", "author", "authorName", "authorId",
    "publisher", "publisherName", "publisherId", "category", "categoryName", "categoryId",
    "edition", "publicationYear", "language", "subject", "description",
    "pages", "shelfLocation", "coverImageUrl", "status"
  ];

  allowedFields.forEach(f => {
    if (req.body[f] !== undefined) {
      book[f] = req.body[f];
    }
  });
  book.updatedAt = new Date().toISOString();

  // Sync with Supabase public.library_books
  if (supabase) {
    try {
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      const targetDbId = book.db_id || (isUuid.test(req.params.id) ? req.params.id : null);
      if (targetDbId) {
        await supabase
          .from("library_books")
          .update({
            title: book.title,
            author: book.author || book.authorName,
            category: book.category || book.categoryName,
            publisher: book.publisher || book.publisherName,
            isbn: book.isbn
          })
          .eq("id", targetDbId);
      }
    } catch (e) {
      console.warn("[DB] library_books update exception:", e.message);
    }
  }

  ERP_AUDIT_LOGS.unshift({
    id: `aud-${Date.now()}`,
    action: "erp.library_book_updated",
    user_email: req.user?.email || "librarian@dpsheritage.edu.in",
    target_type: "library_book",
    target_id: book.id,
    ip_address: req.ip || "127.0.0.1",
    timestamp: new Date().toISOString()
  });

  res.json({ success: true, message: "Book metadata updated successfully", book });
});

app.delete("/api/erp/library/books/:id", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const book = ERP_LIBRARY_BOOKS.find(b => b.id === req.params.id && b.organization_id === orgId);
  if (!book) {
    return res.status(404).json({ success: false, message: "Book not found" });
  }

  // Check active loans
  const hasActiveLoan = ERP_LIBRARY_TRANSACTIONS.some(t => t.bookId === book.id && (t.status === "issued" || t.status === "overdue"));
  if (hasActiveLoan) {
    return res.status(400).json({ success: false, message: "Cannot archive book while active copies are issued to members" });
  }

  book.status = "archived";
  book.updatedAt = new Date().toISOString();

  ERP_AUDIT_LOGS.unshift({
    id: `aud-${Date.now()}`,
    action: "erp.library_book_archived",
    user_email: req.user?.email || "librarian@dpsheritage.edu.in",
    target_type: "library_book",
    target_id: book.id,
    ip_address: req.ip || "127.0.0.1",
    timestamp: new Date().toISOString()
  });

  res.json({ success: true, message: "Book archived from active circulation", book });
});

